from evaluate_all_rules import results, ref_seq
from collections import Counter

def classify_candidates(results):
    assigned = []
    for r in results:
        c = r['cand']
        t_supp = r['t_supp']
        t_cov = r['t_cov']
        n_alt = r['n_alt']
        n_depth = r['n_depth']
        t_alt = r['t_alt']
        t_depth = r['t_depth']
        pos = c['pos']
        is_del = len(c['ref']) != len(c['alt'])
        tag = None
        if n_alt >= 2 and n_depth > 0 and (n_alt / n_depth) >= 0.05:
            tag = 'GERMLINE'
        elif t_alt < 4:
            tag = 'LOW_SUPPORT'
        elif not is_del and sum(1 for read in t_supp if read['aligned_ref'][pos][2] < 20) / t_alt >= 0.75:
            tag = 'LOW_BASE_QUALITY'
        elif sum(1 for read in t_supp if read['mapq'] < 20) / t_alt >= 0.75:
            tag = 'LOW_MAPPING_QUALITY'
        else:
            mismatches = []
            for read in t_supp:
                f = sum(1 for rp, (qi, b, q) in read['aligned_ref'].items() if (rp != pos if not is_del else True) and b != ref_seq[rp - 1])
                mismatches.append(f)
            if sum(mismatches) / len(mismatches) >= 4.0:
                tag = 'MULTI_MISMATCH'
        if tag is None:
            cov_pos = sum(1 for read in t_cov if read['strand'] == '+')
            cov_neg = sum(1 for read in t_cov if read['strand'] == '-')
            if cov_pos > 0 and cov_neg > 0:
                supp_pos = sum(1 for read in t_supp if read['strand'] == '+')
                supp_neg = sum(1 for read in t_supp if read['strand'] == '-')
                if max(supp_pos, supp_neg) / t_alt >= 0.90:
                    tag = 'STRAND_BIAS'
        if tag is None:
            if not is_del:
                re_count = sum(1 for read in t_supp if read['aligned_ref'][pos][0] < 5 or read['aligned_ref'][pos][0] >= len(read['seq']) - 5)
                if re_count / t_alt >= 0.75:
                    tag = 'READ_END'
        if tag is None:
            disc_count = sum(1 for read in t_supp if abs(read['tlen']) > 1000)
            if disc_count / t_alt >= 0.75:
                tag = 'DISCORDANT_PAIRS'
        assigned.append({'res': r, 'tag': tag})
    for i in range(len(assigned) - 1):
        it1, it2 = assigned[i], assigned[i+1]
        c1, c2 = it1['res']['cand'], it2['res']['cand']
        if len(c1['ref']) == 1 and len(c1['alt']) == 1 and len(c2['ref']) == 1 and len(c2['alt']) == 1 and c2['pos'] == c1['pos'] + 1:
            if it1['tag'] is None and it2['tag'] is None:
                m1 = set(r['qname'] for r in it1['res']['t_supp'])
                m2 = set(r['qname'] for r in it2['res']['t_supp'])
                frac = len(m1.intersection(m2)) / len(m1.union(m2))
                print(f'MNV check {c1["id"]}-{c2["id"]}: {frac:.3f}')
                if frac >= 0.90:
                    it1['tag'] = 'PASS'
                    it2['tag'] = 'MNV_PARTNER'
    for it in assigned:
        if it['tag'] is None: it['tag'] = 'PASS'
        it['call'] = 'somatic' if it['tag'] == 'PASS' else 'fail'
    return assigned

classified = classify_candidates(results)
counts = Counter(it['tag'] for it in classified)
print('Tag counts:', dict(counts))
